93:         };
94:         match b {
95:             b'(' => { self.pos += 1; Ok(Some(single(None))) }
96:             b')' => { self.pos += 1; Ok(Some(single(None))) }
97:             b',' => { self.pos += 1; Ok(Some(single(None))) }
98:             b'+' => { self.pos += 1; Ok(Some(single(Some(Op::Add)))) }
99:             b'-' => { self.pos += 1; Ok(Some(single(Some(Op::Sub)))) }
100:             b'*' => { self.pos += 1; Ok(Some(single(Some(Op::Mul)))) }
101:             b'/' => { self.pos += 1; Ok(Some(single(Some(Op::Div)))) }
102:             b'%' => { self.pos += 1; Ok(Some(single(Some(Op::Rem)))) }
103:             b'^' => { self.pos += 1; Ok(Some(single(Some(Op::Pow)))) }
104:             _ if b.is_ascii_digit() || b == b'.' => {
105:                 let (val, end) = Self::read_number(self.bytes, start)?;
106:                 self.pos = end;
107:                 Ok(Some(Tok::Num(val, start)))
108:             }
109:             _ if b == b'_' || b.is_ascii_alphabetic() => {
110:                 let start = self.pos;
111:                 while self.pos < n && (self.bytes[self.pos] == b'_'
112:                     || self.bytes[self.pos].is_ascii_alphabetic()
113:                     || self.bytes[self.pos].is_ascii_digit())
114:                 {
115:                     self.pos += 1;
116:                 }
117:                 let name: String = self.bytes[start..self.pos].iter().map(|&c| c as char).collect();
118:                 Ok(Some(Tok::Ident(name, start)))
119:             }
120:             _ => Err(Error::UnexpectedChar(start)),
121:         }
122:     }
123: 
124:     /// Reads a number starting at `at` (a digit or `.`) and returns its value
125:     /// and the position just past it. A number is digits, an optional
126:     /// fraction (a `.` only counts when followed by digits) and an optional
127:     /// well-formed exponent (`e`/`E`, optional sign, at least one digit).
128:     /// A lone `.` (no digits at all) can't start a token.
129:     fn read_number(bytes: &[u8], at: usize) -> Result<(f64, usize), Error> {
130:         let n = bytes.len();
131:         let mut pos = at;
132:         let mut seen_digit = false;
133:         while pos < n && bytes[pos].is_ascii_digit() {
134:             pos += 1;
135:             seen_digit = true;
136:         }
137:         if pos < n && bytes[pos] == b'.' && pos + 1 < n && bytes[pos + 1].is_ascii_digit() {
138:             pos += 1;
139:             while pos < n && bytes[pos].is_ascii_digit() {
140:                 pos += 1;
141:             }
142:         }
143:         if pos < n && (bytes[pos] == b'e' || bytes[pos] == b'E') {
144:             let mut q = pos + 1;
145:             if q < n && (bytes[q] == b'+' || bytes[q] == b'-') {
146:                 q += 1;
147:             }
148:             if q < n && bytes[q].is_ascii_digit() {
149:                 pos = q;
150:                 while pos < n && bytes[pos].is_ascii_digit() {
151:                     pos += 1;
152:                 }
153:             }
154:         }
155:         if !seen_digit {
156:             return Err(Error::UnexpectedChar(at));
157:         }
158:         let text: String = bytes[at..pos].iter().map(|&c| c as char).collect();
159:         let val: f64 = text.parse().unwrap();
160:         Ok((val, pos))
161:     }
162: }
163: 
164: // ---------------------------------------------------------------------------
165: // Parser
166: // ---------------------------------------------------------------------------
167: 
168: #[derive(Debug)]
169: enum Expr {
170:     Num(f64),
171:     Var(String),
172:     Call(String, Vec<Expr>),
173:     Neg(Box<Expr>),
174:     Bin(Op, Box<Expr>, Box<Expr>),
175: }
176: 
177: struct Parser<'a> {
178:     lexer: Lexer<'a>,
179:     vars: &'a HashMap<String, f64>,
180:     peeked: Option<Tok>,
181: }
182: 
183: impl<'a> Parser<'a> {
184:     fn new(src: &'a str, vars: &'a HashMap<String, f64>) -> Self {
185:         Parser { lexer: Lexer::new(src), vars, peeked: None }
186:     }
187: 
188:     /// Returns the next token without consuming it, lexing on demand so that
189:     /// errors surface left to right.
190:     fn peek(&mut self) -> Result<Option<Tok>, Error> {
191:         if self.peeked.is_none() {
192:             self.peeked = self.lexer.next_token()?;
193:         }
194:         Ok(self.peeked.clone())
195:     }
196: 
197:     fn advance(&mut self) -> Result<Option<Tok>, Error> {
198:         let t = self.peek()?;
199:         self.peeked = None;
200:         Ok(t)
201:     }
202: 
203:     /// Parses the whole expression and rejects trailing tokens.
204:     fn finish(&mut self, e: Expr) -> Result<f64, Error> {
205:         match self.peek()? {
206:             Some(t) => Err(Error::UnexpectedToken(t.pos())),
207:             None => eval_expr(&e, self.vars),
208:         }
209:     }
210: 
211:     // expr := additive
212:     fn parse_expr(&mut self) -> Result<Expr, Error> {
213:         self.parse_additive()
214:     }
215: 
216:     // additive := multiplicative ((+|-) multiplicative)*   (left assoc)
217:     fn parse_additive(&mut self) -> Result<Expr, Error> {
218:         let mut left = self.parse_multiplicative()?;
219:         loop {
220:             match self.peek()? {
221:                 Some(Tok::Op(Op::Add, _)) | Some(Tok::Op(Op::Sub, _)) => {
222:                     let op = match self.advance()?.as_ref().unwrap() {
223:                         Tok::Op(o, _) => *o,
224:                         _ => unreachable!(),
225:                     };
226:                     let right = self.parse_multiplicative()?;
227:                     left = Expr::Bin(op, Box::new(left), Box::new(right));
228:                 }
229:                 _ => break,
230:             }
231:         }
232:         Ok(left)
233:     }
234: 
235:     // multiplicative := unary (('*'|'/'|'%') unary)*   (left assoc)
236:     fn parse_multiplicative(&mut self) -> Result<Expr, Error> {
237:         let mut left = self.parse_unary()?;
238:         loop {
239:             match self.peek()? {
240:                 Some(Tok::Op(Op::Mul, _))
241:                 | Some(Tok::Op(Op::Div, _))
242:                 | Some(Tok::Op(Op::Rem, _)) => {
243:                     let op = match self.advance()?.as_ref().unwrap() {
244:                         Tok::Op(o, _) => *o,
245:                         _ => unreachable!(),
246:                     };
247:                     let right = self.parse_unary()?;
248:                     left = Expr::Bin(op, Box::new(left), Box::new(right));
249:                 }
250:                 _ => break,
251:             }
252:         }
253:         Ok(left)
254:     }
255: 
256:     // unary := ('-'|'+')* power    (signs repeat: --2 == 2)
257:     fn parse_unary(&mut self) -> Result<Expr, Error> {
258:         let mut negs = 0usize;
259:         loop {
260:             match self.peek()? {
261:                 Some(Tok::Op(Op::Sub, _)) => { self.advance()?; negs += 1; }
262:                 Some(Tok::Op(Op::Add, _)) => { self.advance()?; }
263:                 _ => break,
264:             }
265:         }
266:         let base = self.parse_power()?;
267:         if negs % 2 == 1 {
268:             Ok(Expr::Neg(Box::new(base)))
269:         } else {
270:             Ok(base)
271:         }
272:     }
273: 
274:     // power := primary ('^' unary)?   (right assoc; '^' binds tighter than
275:     // unary minus, and the exponent is a unary expression)
276:     fn parse_power(&mut self) -> Result<Expr, Error> {
277:         let base = self.parse_primary()?;
278:         if let Some(Tok::Op(Op::Pow, _)) = self.peek()? {
279:             self.advance()?;
280:             let exp = self.parse_unary()?;
281:             Ok(Expr::Bin(Op::Pow, Box::new(base), Box::new(exp)))
282:         } else {
283:             Ok(base)
284:         }
285:     }
286: 
287:     // primary := number | ident | ident '(' args ')' | '(' expr ')'
288:     fn parse_primary(&mut self) -> Result<Expr, Error> {
289:         match self.advance()?.ok_or(Error::UnexpectedEnd)? {
290:             Tok::Num(v, _) => Ok(Expr::Num(v)),
291:             Tok::Ident(name, _) => {
292:                 if matches!(self.peek()?, Some(Tok::LParen(_))) {
293:                     self.advance()?; // '('
294:                     let mut args = Vec::new();
295:                     if !matches!(self.peek()?, Some(Tok::RParen(_))) {
296:                         args.push(self.parse_expr()?);
297:                         while matches!(self.peek()?, Some(Tok::Comma(_))) {
298:                             self.advance()?; // ','
299:                             args.push(self.parse_expr()?);
300:                         }
301:                     }
302:                     match self.advance()?.ok_or(Error::UnexpectedEnd)? {
303:                         Tok::RParen(_) => Ok(Expr::Call(name, args)),
304:                         t => Err(Error::UnexpectedToken(t.pos())),
305:                     }
306:                 } else {
307:                     Ok(Expr::Var(name))
308:                 }
309:             }
310:             Tok::LParen(_) => {
311:                 let e = self.parse_expr()?;
312:                 match self.advance()?.ok_or(Error::UnexpectedEnd)? {
313:                     Tok::RParen(_) => Ok(e),
314:                     t => Err(Error::UnexpectedToken(t.pos())),
315:                 }
316:             }
317:             t => Err(Error::UnexpectedToken(t.pos())),
318:         }
319:     }
320: }
321: 
322: // ---------------------------------------------------------------------------
323: // Evaluation
324: // ---------------------------------------------------------------------------
325: 
326: fn eval_expr(e: &Expr, vars: &HashMap<String, f64>) -> Result<f64, Error> {
327:     match e {
328:         Expr::Num(v) => Ok(*v),
329:         Expr::Var(name) => {
330:             vars.get(name).copied().ok_or_else(|| Error::UnknownVariable(name.clone()))
331:         }
332:         Expr::Neg(inner) => Ok(-eval_expr(inner, vars)?),
333:         Expr::Bin(op, l, r) => {
334:             let a = eval_expr(l, vars)?;
335:             let b = eval_expr(r, vars)?;
336:             match op {
337:                 Op::Add => Ok(a + b),
338:                 Op::Sub => Ok(a - b),
339:                 Op::Mul => Ok(a * b),
340:                 Op::Div => {
341:                     if b == 0.0 { Err(Error::DivisionByZero) } else { Ok(a / b) }
342:                 }
343:                 Op::Rem => {
344:                     if b == 0.0 { Err(Error::DivisionByZero) } else { Ok(a % b) }
345:                 }
346:                 Op::Pow => Ok(a.powf(b)),
347:             }
348:         }
349:         Expr::Call(name, args) => eval_call(name, args, vars),
350:     }
351: }
352: 
353: fn eval_call(name: &str, args: &[Expr], vars: &HashMap<String, f64>) -> Result<f64, Error> {
354:     // The call site sits left of its arguments, so unknown-function and
355:     // arity errors are reported before any errors inside the arguments.
356:     let known = match name {
357:         "abs" | "sqrt" => args.len() == 1,
358:         "min" | "max" => !args.is_empty(),
359:         _ => return Err(Error::UnknownFunction(name.to_owned())),
360:     };
361:     if !known {
362:         return Err(Error::Arity(name.to_owned(), args.len()));
363:     }
364:     let vals: Result<Vec<f64>, Error> =
365:         args.iter().map(|a| eval_expr(a, vars)).collect();
366:     let vals = vals?;
367:     match name {
368:         "abs" => Ok(vals[0].abs()),
369:         "sqrt" => Ok(vals[0].sqrt()),
370:         "min" => Ok(vals.iter().copied().fold(f64::INFINITY, f64::min)),
371:         "max" => Ok(vals.iter().copied().fold(f64::NEG_INFINITY, f64::max)),
372:         _ => unreachable!(),
373:     }
374: }

